find_min_cmov:
    # a0 = array address
    # a1 = array length
    # Returns: a0 = minimum value
    la a0, array
    li a1, 1000
    
    lw      a2, 0(a0)           # a2 = min = array[0]
    li      t0, 1               # t0 = i = 1
    
min_loop_cmov:
    bge     t0, a1, min_done_cmov
    slli    t1, t0, 2           # t1 = i * 4
    add     t1, t1, a0          # t1 = &array[i]
    lw      t2, 0(t1)           # t2 = array[i]
    
    cmov    a2, a2, t2, 1       # a2 = min(a2, t2) - SINGLE INSTRUCTION!
    
    addi    t0, t0, 1
    beq x0, x0, min_loop_cmov
    
min_done_cmov:
    mv      a0, a2